//! What a budget action's HISTORY says happened.
//!
//! `ActionHistoryDetails$Message` is "the description of the details for the event" and
//! `ActionHistory$EventType` "distinguishes between whether the events are triggered by
//! the user or are generated by the system". So the RULE asserted here:
//!
//! > a history record's `Message` is the sentence its `EventType` fixes — the ACTOR and
//! > what was done to the action — and carries no variable part at all: every other member
//! > of the record (`Status`, `Timestamp`, the embedded `Action`) already states what that
//! > particular event did. An event a caller triggered is worded from the customer's point
//! > of view; the one event type no caller triggers names the system.
//!
//! The tables span what the rule generalises over: every `EventType` a read of this
//! service can report (the create, an update, an execution and the settle the clock owes
//! it), the member an update names, the action the history belongs to, and the page size
//! the history is read at.
//!
//! The harness (`router`, `call`, `caller_account`) and the request builders are the
//! sibling action suites', so every suite in this target drives the service the same way.

use serde_json::{json, Value};

/// The `EventType` catalog is not re-typed here: this is the model-derived constant the
/// scaffold generated into `src/ops/types/shared_types.rs`, so a table built from it
/// cannot drift from the model.
use service_com_amazonaws_budgets_awsbudgetservicegateway::ops::types::EVENT_TYPE_VALUES;
use service_com_amazonaws_budgets_awsbudgetservicegateway::state::{
    ACTION_SETTLES_AFTER, EVENT_TYPE_CREATE_ACTION, EVENT_TYPE_EXECUTE_ACTION, EVENT_TYPE_SYSTEM,
    EVENT_TYPE_UPDATE_ACTION, EXECUTION_TYPE_APPROVE,
};

use super::budget_action_execution::{
    create_body, definition_for, email_subscriber, execute_action, iam_definition,
    pending_create_body, seed_budget, seed_pending_action, simple_create_body, sns_subscriber,
};
use super::budget_action_history::read_history;
use super::budget_lifecycle::{caller_account, call, router};

/// What a history record of each `EventType` says, and nothing else: the actor and what
/// was done to the action.
///
/// The catalog is the modelled `EventType` (`smithy_query(query="shape",
/// shape="EventType")`). `DELETE_ACTION` is not listed: the records of an action go with
/// the action its delete removes, so no read can report one.
const EVENT_MESSAGES: &[(&str, &str)] = &[
    (EVENT_TYPE_CREATE_ACTION, "Customer created a budget action."),
    (EVENT_TYPE_UPDATE_ACTION, "Customer updated a budget action."),
    (
        EVENT_TYPE_EXECUTE_ACTION,
        "Customer executed a budget action.",
    ),
    (EVENT_TYPE_SYSTEM, "System updated a budget action."),
];

/// The message [`EVENT_MESSAGES`] fixes for `event_type`.
fn event_message(event_type: &str) -> &'static str {
    EVENT_MESSAGES
        .iter()
        .find(|(event, _)| *event == event_type)
        .map(|(_, message)| *message)
        .unwrap_or_else(|| panic!("no message is pinned for the event type {event_type}"))
}

/// The `Message` of one history record.
fn record_message(record: &Value) -> &str {
    record["ActionHistoryDetails"]["Message"]
        .as_str()
        .unwrap_or_default()
}

/// RULE: each history record carries the sentence its `EventType` fixes, whichever call
/// wrote it.
///
/// The history walked covers all four event types a read of this service can report, with
/// one update per member `UpdateBudgetAction` takes, so the update wording is asserted
/// over a SET of updates rather than one.
#[tokio::test]
async fn every_history_record_carries_the_wording_its_event_type_fixes() {
    for (event, message) in EVENT_MESSAGES {
        assert!(
            EVENT_TYPE_VALUES.contains(event),
            "setup: expected {event} to be a modelled EventType, got {EVENT_TYPE_VALUES:?}"
        );
        assert!(
            !message.is_empty(),
            "setup: expected a sentence for {event}, got an empty one"
        );
    }

    let router = router();
    let account_id = caller_account();
    let budget_name = "history-wording";
    seed_budget(&router, &account_id, budget_name).await;
    // Created WAITING for its approval, so the execution below is accepted and the settle
    // it owes follows on the clock alone.
    let action_id = seed_pending_action(&router, &account_id, budget_name).await;

    let updates = [
        ("the approval model", json!({"ApprovalModel": "AUTOMATIC"})),
        (
            "the threshold",
            json!({"ActionThreshold": {
                "ActionThresholdValue": 70.0,
                "ActionThresholdType": "PERCENTAGE"
            }}),
        ),
        (
            "the subscribers",
            json!({"Subscribers": [email_subscriber(7)]}),
        ),
    ];
    let mut expected: Vec<&str> = vec![EVENT_TYPE_CREATE_ACTION];
    for (case, patch) in updates {
        let mut request = json!({
            "AccountId": &account_id,
            "BudgetName": budget_name,
            "ActionId": &action_id
        });
        for (member, value) in patch.as_object().expect("the patch is an object") {
            request[member] = value.clone();
        }
        let (http, body) = call(&router, "UpdateBudgetAction", &request).await;
        assert_eq!(
            http, 200,
            "case {case:?}: expected the update to be served, got {http} {body}"
        );
        expected.push(EVENT_TYPE_UPDATE_ACTION);
    }

    let (http, body) = execute_action(
        &router,
        &account_id,
        budget_name,
        &action_id,
        EXECUTION_TYPE_APPROVE,
    )
    .await;
    assert_eq!(
        http, 200,
        "expected the approval to be served, got {http} {body}"
    );
    expected.push(EVENT_TYPE_EXECUTE_ACTION);
    // No call makes the settle: the span passes and its record is there.
    tokio::time::sleep(ACTION_SETTLES_AFTER * 2).await;
    expected.push(EVENT_TYPE_SYSTEM);

    let records = read_history(&router, &account_id, budget_name, &action_id, None, "wording").await;
    let reported: Vec<&str> = records
        .iter()
        .map(|record| record["EventType"].as_str().unwrap_or_default())
        .collect();
    assert_eq!(
        reported, expected,
        "expected the history to hold {expected:?} oldest first, got {reported:?}"
    );
    for (index, record) in records.iter().enumerate() {
        let event = record["EventType"].as_str().unwrap_or_default();
        let case = format!("record {index} ({event})");
        assert_eq!(
            record_message(record),
            event_message(event),
            "case {case:?}: expected the wording its event type fixes, got {record}"
        );
        // Fixed text: no value of the request or of the resource leaks into it.
        for value in [action_id.as_str(), budget_name, account_id.as_str()] {
            assert!(
                !record_message(record).contains(value),
                "case {case:?}: expected no {value:?} in the wording, got {record}"
            );
        }
    }
}

/// Actions differing in every member a caller supplies, for the rule's other side.
fn differing_creates(account_id: &str, budget_name: &str) -> Vec<(&'static str, Value)> {
    vec![
        (
            "an armed IAM-policy action",
            simple_create_body(account_id, budget_name),
        ),
        (
            "an action waiting for its approval",
            pending_create_body(account_id, budget_name),
        ),
        (
            "an SCP action with two subscribers and tags",
            create_body(
                account_id,
                budget_name,
                "APPLY_SCP_POLICY",
                &definition_for("APPLY_SCP_POLICY"),
                "AUTOMATIC",
                "FORECASTED",
                &json!({"ActionThresholdValue": 42.5, "ActionThresholdType": "ABSOLUTE_VALUE"}),
                &json!([email_subscriber(8), sns_subscriber()]),
                Some(json!([{"Key": "team", "Value": "platform"}])),
            ),
        ),
        (
            "an SSM action at the threshold minimum",
            create_body(
                account_id,
                budget_name,
                "RUN_SSM_DOCUMENTS",
                &definition_for("RUN_SSM_DOCUMENTS"),
                "MANUAL",
                "FORECASTED",
                &json!({"ActionThresholdValue": 0.0, "ActionThresholdType": "PERCENTAGE"}),
                &json!([email_subscriber(9)]),
                None,
            ),
        ),
        (
            "an IAM action at the threshold maximum",
            create_body(
                account_id,
                budget_name,
                "APPLY_IAM_POLICY",
                &iam_definition(),
                "AUTOMATIC",
                "ACTUAL",
                &json!({
                    "ActionThresholdValue": 15_000_000_000_000.0_f64,
                    "ActionThresholdType": "PERCENTAGE"
                }),
                &json!([email_subscriber(10)]),
                None,
            ),
        ),
    ]
}

/// RULE, the other side: the wording is the EVENT's, not the action's — actions differing
/// in every member a caller supplies carry the same create wording, and a paginated read
/// reports it unchanged.
#[tokio::test]
async fn the_create_wording_does_not_depend_on_the_action_or_the_page() {
    let router = router();
    let account_id = caller_account();
    let budget_name = "history-wording-pages";
    seed_budget(&router, &account_id, budget_name).await;

    let mut created: Vec<(&'static str, String)> = Vec::new();
    for (case, create) in differing_creates(&account_id, budget_name) {
        let (http, body) = call(&router, "CreateBudgetAction", &create).await;
        assert_eq!(
            http, 200,
            "case {case:?}: expected CreateBudgetAction to answer 200, got {http} {body}"
        );
        created.push((
            case,
            body["ActionId"].as_str().unwrap_or_default().to_string(),
        ));
    }

    // Every page size from one record per page up to more than the history holds.
    for page in [None, Some(1), Some(2), Some(100)] {
        for (case, action_id) in &created {
            let case = format!("{case} at page size {page:?}");
            let records =
                read_history(&router, &account_id, budget_name, action_id, page, &case).await;
            assert_eq!(
                records.len(),
                1,
                "case {case:?}: expected the create record alone, got {records:?}"
            );
            assert_eq!(
                record_message(&records[0]),
                event_message(EVENT_TYPE_CREATE_ACTION),
                "case {case:?}: expected the create wording, got {}",
                records[0]
            );
        }
    }
}
